    val windSpeed: Double? get() = state.windSpeed
    val availableStates get() = state.availableStates

    companion object {
        const val CLEAR_NIGHT = "clear-night"
        const val CLOUDY = "cloudy"
        const val FOG = "fog"
        const val HAIL = "hail"
        const val LIGHTNING = "lightning"
        const val LIGHTNING_RAINY = "lightning-rainy"
        const val PARTLY_CLOUDY = "partlycloudy"
        const val POURING = "pouring"
        const val RAINY = "rainy"
        const val SNOWY = "snowy"
        const val SNOWY_RAINY = "snowy-rainy"
        const val SUNNY = "sunny"
        const val WINDY = "windy"
        const val WINDY_VARIANT = "windy-variant"
        const val EXCEPTIONAL = "exceptional"
    }
}

// InputBoolean
open class InputBooleanState(entityId: String) : EntityState(entityId) {
    val ON = "on"
    val OFF = "off"
    override val availableStates: List<String> = listOf(ON, OFF, UNAVAILABLE, UNKNOWN)
}

open class InputBooleanEntity(entityId: String) : Entity(entityId) {
    override val state: InputBooleanState = InputBooleanState(entityId)
    val ON get() = state.ON
    val OFF get() = state.OFF
    val availableStates get() = state.availableStates

    companion object {
        const val ON = "on"
        const val OFF = "off"
        val ALL_STATES = listOf(ON, OFF, UNAVAILABLE, UNKNOWN)
    }
}

// Update
open class UpdateState(entityId: String) : EntityState(entityId) {
    val ON = "on"
    val OFF = "off"
    val UPDATE_AVAILABLE = "on"
    val UP_TO_DATE = "off"
    val isUpdateAvailable: Boolean get() = isOn
    override val availableStates: List<String> = listOf(ON, OFF, UNAVAILABLE, UNKNOWN)
}

open class UpdateEntity(entityId: String) : Entity(entityId) {
    override val state: UpdateState = UpdateState(entityId)
    val ON get() = state.ON
    val OFF get() = state.OFF
    val UPDATE_AVAILABLE get() = state.UPDATE_AVAILABLE
    val UP_TO_DATE get() = state.UP_TO_DATE
    val isUpdateAvailable: Boolean get() = state.isUpdateAvailable
    val availableStates get() = state.availableStates

    companion object {
        const val ON = "on"
        const val OFF = "off"
        const val UPDATE_AVAILABLE = "on"
        const val UP_TO_DATE = "off"
    }
}

