// Select
open class SelectState(entityId: String) : EntityState(entityId) {
    open val options: List<String> get() = (current?.attributes?.get("options") as? JsonArray)?.mapNotNull { (it as? JsonPrimitive)?.content } ?: emptyList()
    override val availableStates: List<String> get() = options + listOf(UNAVAILABLE, UNKNOWN)
}

open class SelectEntity(entityId: String) : Entity(entityId) {
    override val state: SelectState = SelectState(entityId)
    open val options: List<String> get() = state.options
    val availableStates get() = state.availableStates
}

// Sensor
open class SensorState(entityId: String) : EntityState(entityId) {
    val numericValue: Double? get() = raw.toDoubleOrNull()
    val unitOfMeasurement: String? get() = current?.getAttrString("unit_of_measurement")
    val deviceClass: String? get() = current?.getAttrString("device_class")
}

open class SensorEntity(entityId: String) : Entity(entityId) {
    override val state: SensorState = SensorState(entityId)
    val numericValue: Double? get() = state.numericValue
    val unitOfMeasurement: String? get() = state.unitOfMeasurement
    val deviceClass: String? get() = state.deviceClass
}

// Button
open class ButtonState(entityId: String) : EntityState(entityId)
open class ButtonEntity(entityId: String) : Entity(entityId) {
    override val state: ButtonState = ButtonState(entityId)
}

// Generic
